bool hasPair(const std::vector<long long>& nums, long long target) {
    int left = 0;
    int right = (int)nums.size() - 1;
    while (left < right) {
        long long total = nums[left] + nums[right];
        if (total == target) return true;
        if (total < target) left++;
        else right--;
    }
    return false;
}

